final class METPurchLineHistory_Extension
{

}

Method.Source:
    public void insert()
    {
        this.METPurchaseWMSFactor = METPurchLine::find(PurchLine::findInventTransId(this.InventTransId).RecId).PurchaseWMSFactor;

        next insert();
    }

    /// <summary>
    /// Initializing the purch line history from purch line data.
    /// </summary>
    /// <param name = "_purchLine">_purchLine</param>
    public void initFromPurchLine(PurchLine _purchLine)
    {
        next initFromPurchLine(_purchLine);

        PurchLineHistory purchLineHistory = this;

        purchLineHistory.METPurchaseWMSFactor = METPurchLine::find(_purchLine.RecId).PurchaseWMSFactor;
    }
